def sum_even(nums):
    total=0
    for x in nums:
        if x % 2 == 0: total += x
    return total

def dedupe_keep_order(items):
    seen=set(); out=[]
    for x in items:
        if x not in seen:
            seen.add(x); out.append(x)
    return out

def product_nonzero(nums):
    p=1
    for x in nums:
        if x != 0: p *= x
    return p

def has_pair_sum(nums, target):
    seen=set()
    for x in nums:
        if target-x in seen: return True
        seen.add(x)
    return False
